// "Add date table": a calendar table generated by one SQL data step, related to a date column of the model.
// It covers whole (fiscal) years around the source column's dates and is rebuilt with the data, so it grows when new
// dates arrive. ADR 0006, decision 6: a fiscal year start, a week start day and ISO weeks.
import type { DataStep, Hierarchy, Relationship, Report, TableSettings } from './types.js';
import { quoteIdent } from './sql.js';

export interface DateTableOptions {
  /** The calendar table's name. Default `calendar`. */
  table?: string;
  /** The date column it describes, as `table.column` (dates as ISO text or a date type). */
  source: string;
  /** The month the fiscal year starts in (1–12). Default 1: the calendar year. A fiscal year is named by the year it ends in. */
  fiscalStart?: number;
  /** The first day of the week: 1 Monday (default), 0 Sunday. Sets day-of-week order and week numbers. */
  weekStart?: 0 | 1;
  /** Add ISO 8601 week-year and week columns. */
  isoWeeks?: boolean;
}

/** What the model remembers about its date table (time-intelligence measures read it). */
export interface DateTableSpec {
  table: string;
  /** The calendar's date column (its key). */
  column: string;
  source: string;
  fiscalStart: number;
  weekStart: 0 | 1;
  isoWeeks: boolean;
}

export interface DateTablePlan {
  spec: DateTableSpec;
  step: DataStep;
  relationship: Relationship;
  hierarchies: Hierarchy[];
  settings: TableSettings;
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const caseOf = (expr: string, names: string[], base: number) => `CASE ${expr} ${names.map((n, i) => `WHEN ${i + base} THEN '${n}'`).join(' ')} END`;

/** Plan a date table: the data step that builds it, its relationship, hierarchies and display settings. */
export function planDateTable(o: DateTableOptions): DateTablePlan {
  const table = o.table?.trim() || 'calendar';
  const fiscalStart = Math.min(12, Math.max(1, Math.round(o.fiscalStart ?? 1)));
  const weekStart = o.weekStart === 0 ? 0 : 1;
  const isoWeeks = !!o.isoWeeks;
  const dot = o.source.indexOf('.');
  if (dot < 1) throw new Error(`the date column must be "table.column", not "${o.source}"`);
  const srcTable = o.source.slice(0, dot);
  const srcCol = o.source.slice(dot + 1);
  const src = `${quoteIdent(srcTable)}.${quoteIdent(srcCol)}`;
  const fiscal = fiscalStart !== 1;

  // The first day of the (fiscal) year holding a date, as SQL over that date expression.
  const yearStart = (d: string) =>
    fiscal
      ? `date(${d}, 'start of month', '-' || ((CAST(strftime('%m', ${d}) AS INTEGER) - ${fiscalStart} + 12) % 12) || ' months')`
      : `date(${d}, 'start of year')`;
  const m = `CAST(strftime('%m', d) AS INTEGER)`;
  const w = `CAST(strftime('%w', d) AS INTEGER)`;
  const dow = weekStart === 1 ? `((${w} + 6) % 7) + 1` : `${w} + 1`;
  const cols: [string, string, string][] = [
    // [column, SQL type, expression over d]
    ['date', 'TEXT PRIMARY KEY', 'd'],
    ['year', 'TEXT', `strftime('%Y', d)`],
    ['quarter', 'TEXT', `'Q' || ((${m} + 2) / 3)`],
    ['month', 'INTEGER', m],
    ['month_name', 'TEXT', caseOf(m, MONTHS, 1)],
    ['year_month', 'TEXT', `strftime('%Y-%m', d)`],
    ['day', 'INTEGER', `CAST(strftime('%d', d) AS INTEGER)`],
    ['day_of_week', 'INTEGER', dow],
    ['day_name', 'TEXT', caseOf(w, DAYS, 0)],
    ['week', 'INTEGER', `CAST(strftime('${weekStart === 1 ? '%W' : '%U'}', d) AS INTEGER)`],
    ['week_start', 'TEXT', `date(d, '-' || (${dow} - 1) || ' days')`],
  ];
  if (isoWeeks) {
    cols.push(['iso_year', 'TEXT', `strftime('%G', d)`], ['iso_week', 'INTEGER', `CAST(strftime('%V', d) AS INTEGER)`], ['iso_year_week', 'TEXT', `strftime('%G-W%V', d)`]);
  }
  if (fiscal) {
    const fm = `((${m} - ${fiscalStart} + 12) % 12) + 1`;
    cols.push(
      // Named by the year it ends in: with a July start, July 2024 – June 2025 is FY2025.
      ['fiscal_year', 'TEXT', `'FY' || strftime('%Y', date(d, 'start of month', '+${(13 - fiscalStart) % 12} months'))`],
      ['fiscal_quarter', 'TEXT', `'FQ' || ((${fm} + 2) / 3)`],
      ['fiscal_month', 'INTEGER', fm],
      ['fiscal_month_name', 'TEXT', caseOf(m, MONTHS, 1)],
    );
  }
  const t = quoteIdent(table);
  const sql = [
    `-- Date table for ${o.source}: whole ${fiscal ? 'fiscal ' : ''}years around its dates (added by "Add date table").`,
    `DROP TABLE IF EXISTS ${t};`,
    `CREATE TABLE ${t} (${cols.map(([c, type]) => `${quoteIdent(c)} ${type}`).join(', ')});`,
    `INSERT INTO ${t} (${cols.map(([c]) => quoteIdent(c)).join(', ')})`,
    `WITH RECURSIVE days(d) AS (`,
    `  SELECT ${yearStart(`(SELECT min(${src}) FROM ${quoteIdent(srcTable)})`)}`,
    `  UNION ALL SELECT date(d, '+1 day') FROM days`,
    `  WHERE d < date(${yearStart(`(SELECT max(${src}) FROM ${quoteIdent(srcTable)})`)}, '+12 months', '-1 day')`,
    `)`,
    `SELECT ${cols.map(([, , e]) => e).join(', ')} FROM days;`,
  ].join('\n');

  const label: Record<string, { label?: string; sortBy?: string; type?: 'date' | 'text' | 'number'; format?: string; hidden?: boolean }> = {
    date: { label: 'Date', type: 'date', format: 'date' },
    year: { label: 'Year' },
    quarter: { label: 'Quarter' },
    month: { label: 'Month number' },
    month_name: { label: 'Month', sortBy: 'month' },
    year_month: { label: 'Year-month', type: 'date', format: 'month' },
    day: { label: 'Day of month' },
    day_of_week: { label: 'Day of week number' },
    day_name: { label: 'Day of week', sortBy: 'day_of_week' },
    week: { label: 'Week' },
    week_start: { label: 'Week starting', type: 'date', format: 'date' },
    iso_year: { label: 'ISO year' },
    iso_week: { label: 'ISO week' },
    iso_year_week: { label: 'ISO year-week' },
    fiscal_year: { label: 'Fiscal year' },
    fiscal_quarter: { label: 'Fiscal quarter' },
    fiscal_month: { label: 'Fiscal month number' },
    fiscal_month_name: { label: 'Fiscal month', sortBy: 'fiscal_month' },
  };
  const settings: TableSettings = { label: table === 'calendar' ? 'Calendar' : table, columns: Object.fromEntries(cols.map(([c]) => [c, label[c]!])) };
  const hierarchies: Hierarchy[] = [{ table, name: 'Calendar', levels: ['year', 'quarter', 'month_name', 'date'] }];
  if (fiscal) hierarchies.push({ table, name: 'Fiscal calendar', levels: ['fiscal_year', 'fiscal_quarter', 'fiscal_month_name', 'date'] });
  if (isoWeeks) hierarchies.push({ table, name: 'ISO weeks', levels: ['iso_year', 'iso_year_week', 'date'] });
  return {
    spec: { table, column: 'date', source: o.source, fiscalStart, weekStart, isoWeeks },
    step: { sql },
    relationship: { from: o.source, to: `${table}.date` },
    hierarchies,
    settings,
  };
}

/**
 * Add (or replace) the report's date table: the step goes last in the data steps (or, replacing one, where the old one
 * was, so steps that read the calendar after it still run after it), the relationship, hierarchies and display
 * settings into the model, and `model.dateTable` records it. A previous date table is removed first.
 */
export function addDateTable(report: Report, o: DateTableOptions): DateTablePlan {
  const plan = planDateTable(o);
  const old = dateStepIndex(report);
  removeDateTable(report);
  const { table } = plan.spec;
  const steps = (report.data.steps ??= []);
  if (steps.some((s) => 'table' in s && s.table === table)) throw new Error(`a data step already creates a table named "${table}": pick another name`);
  if (old >= 0) steps.splice(old, 0, plan.step);
  else steps.push(plan.step);
  const model = report.model;
  (model.relationships ??= []).push(plan.relationship);
  (model.hierarchies ??= []).push(...plan.hierarchies);
  (model.tables ??= {})[table] = plan.settings;
  model.dateTable = plan.spec;
  return plan;
}

/**
 * Other data steps that read the date table (a year table made from calendar.year): removing the date table would
 * leave them nothing to read, so the data would no longer load.
 */
export function stepsReadingDateTable(report: Report): string[] {
  const spec = report.model.dateTable;
  if (!spec) return [];
  const marker = `-- Date table for ${spec.source}:`;
  const name = spec.table.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const reads = new RegExp(`\\b(FROM|JOIN)\\s+("${name}"|${name})\\b`, 'i');
  return (report.data.steps ?? []).flatMap((s) => ('sql' in s && !s.sql.startsWith(marker) && reads.test(s.sql) ? [s.sql.split('\n')[0]!.replace(/^--\s*/, '')] : []));
}

/** Where the report's date table step is, or -1. */
function dateStepIndex(report: Report): number {
  const spec = report.model.dateTable;
  if (!spec) return -1;
  const marker = `-- Date table for ${spec.source}:`;
  return (report.data.steps ?? []).findIndex((s) => 'sql' in s && s.sql.startsWith(marker));
}

/** Remove the report's date table (its step, relationship, hierarchies and settings). */
export function removeDateTable(report: Report): void {
  const spec = report.model.dateTable;
  if (!spec) return;
  const marker = `-- Date table for ${spec.source}:`;
  report.data.steps = (report.data.steps ?? []).filter((s) => !('sql' in s && s.sql.startsWith(marker)));
  const model = report.model;
  // Its own relationship (from its source column), not others to the calendar, such as a role (the ship date).
  model.relationships = (model.relationships ?? []).filter((r) => !(r.to === `${spec.table}.${spec.column}` && r.from === spec.source && !r.role));
  model.hierarchies = (model.hierarchies ?? []).filter((h) => h.table !== spec.table);
  if (model.tables) delete model.tables[spec.table];
  if (model.layout) delete model.layout[spec.table];
  delete model.dateTable;
}
